    18	function mapRowToBalance(row: BalanceRow): Balance {
    19	  return {
    20	    id: row.id,
    21	    employeeId: row.employee_id,
    22	    leaveType: row.leave_type,
    23	    totalEntitlement: row.total_entitlement,
    24	    usedDays: row.used_days,
    25	    remainingDays: row.remaining_days,
    26	    fiscalYear: row.fiscal_year,
    27	    status: row.status as BalanceStatus,
    28	    createdAt: row.created_at,
    29	    updatedAt: row.updated_at,
    30	  };
    31	}
    32	
    33	const COLUMN_MAP: Record<string, string> = {
    34	  employeeId: 'employee_id',
    35	  leaveType: 'leave_type',
    36	  totalEntitlement: 'total_entitlement',
    37	  usedDays: 'used_days',
    38	  remainingDays: 'remaining_days',
    39	  fiscalYear: 'fiscal_year',
