    43	export class PgBalanceRepository implements IBalanceRepository {
    44	  async findByEmployeeId(employeeId: string): Promise<Balance[]> {
    45	    const result = await pool.query<BalanceRow>(
    46	      'SELECT * FROM balances WHERE employee_id = $1',
    47	      [employeeId],
    48	    );
    49	    return result.rows.map(mapRowToBalance);
    50	  }
    51	
    52	  async findByEmployeeIdAndLeaveType(
    53	    employeeId: string,
    54	    leaveType: string,
    55	  ): Promise<Balance | null> {
    56	    const result = await pool.query<BalanceRow>(
    57	      'SELECT * FROM balances WHERE employee_id = $1 AND leave_type = $2',
    58	      [employeeId, leaveType],
    59	    );
    60	    if (result.rows.length === 0) {
    61	      return null;
    62	    }
    63	    return mapRowToBalance(result.rows[0]);
    64	  }
    65	
    66	  async findByEmployeeIdAndFiscalYear(
    67	    employeeId: string,
    68	    fiscalYear: number,
    69	  ): Promise<Balance[]> {
    70	    const result = await pool.query<BalanceRow>(
    71	      'SELECT * FROM balances WHERE employee_id = $1 AND fiscal_year = $2',
    72	      [employeeId, fiscalYear],
    73	    );
    74	    return result.rows.map(mapRowToBalance);
    75	  }
    76	
    77	  async create(
    78	    balance: Omit<Balance, 'id' | 'createdAt' | 'updatedAt'>,
    79	  ): Promise<Balance> {
    80	    const result = await pool.query<BalanceRow>(
    81	      `INSERT INTO balances (
    82	        employee_id, leave_type, total_entitlement,
    83	        used_days, remaining_days, fiscal_year, status
    84	      ) VALUES ($1, $2, $3, $4, $5, $6, $7)
    85	      RETURNING *`,
    86	      [
    87	        balance.employeeId,
    88	        balance.leaveType,
    89	        balance.totalEntitlement,
    90	        balance.usedDays,
    91	        balance.remainingDays,
    92	        balance.fiscalYear,
    93	        balance.status,
    94	      ],
    95	    );
    96	    return mapRowToBalance(result.rows[0]);
    97	  }
