   130	  async deductDays(id: string, days: number): Promise<Balance | null> {
   131	    const result = await pool.query<BalanceRow>(
   132	      `UPDATE balances
   133	       SET remaining_days = remaining_days - $2,
   134	           used_days = used_days + $2,
   135	           status = CASE WHEN remaining_days - $2 <= 0 THEN 'exhausted' ELSE status END,
   136	           updated_at = NOW()
   137	       WHERE id = $1
   138	       RETURNING *`,
   139	      [id, days],
   140	    );
   141	
   142	    if (result.rows.length === 0) {
   143	      return null;
   144	    }
   145	    return mapRowToBalance(result.rows[0]);
   146	  }
